import{_ as o,a0 as p,w as i,s as d,I as s,x as t,a1 as a,A as n,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const Q=JSON.parse('{"title":"如何在 Linux 系统中创建一个云端加密文件系统 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 系统中创建一个云端加密文件系统 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 系统中创建一个云端加密文件系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 系统中创建一个云端加密文件系统 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20140910 How to create a cloud-based encrypted file system on Linux","title":"如何在 Linux 系统中创建一个云端加密文件系统","tag":"201412","desc":""},"relativePath":"201412/20140910 How to create a cloud-based encrypted file system on Linux.md","filePath":"[post].md"}'),u={name:"201412/20140910 How to create a cloud-based encrypted file system on Linux.md"};function m(f,e,S,L,b,x){const l=p("Link");return i(),d("div",null,[e[31]||(e[31]=s("h1",{id:"如何在-linux-系统中创建一个云端加密文件系统",tabindex:"-1"},[t("如何在 Linux 系统中创建一个云端加密文件系统 "),s("a",{class:"header-anchor",href:"#如何在-linux-系统中创建一个云端加密文件系统","aria-label":"Permalink to “如何在 Linux 系统中创建一个云端加密文件系统”"},"​")],-1)),s("p",null,[a(l,{href:"http://aws.amazon.com/s3"},{default:n(()=>[...e[0]||(e[0]=[t("Amazon S3",-1)])]),_:1}),e[2]||(e[2]=t(" 和 ",-1)),a(l,{href:"http://code.google.com/apis/storage/"},{default:n(()=>[...e[1]||(e[1]=[t("Google Cloud Storage",-1)])]),_:1}),e[3]||(e[3]=t(" 之类的商业云存储服务以能承受的价格提供了高可用性、可扩展、无限容量的对象存储服务。为了加速这些云产品的广泛采用，这些提供商为他们的产品通过明确的 API 和 SDK 培养了一个良好的开发者生态系统。而基于云的文件系统便是这些活跃的开发者社区中的典型产品，已经有了好几个开源的实现。",-1))]),s("p",null,[a(l,{href:"https://bitbucket.org/nikratio/s3ql/"},{default:n(()=>[...e[4]||(e[4]=[t("S3QL",-1)])]),_:1}),e[5]||(e[5]=t(" 便是最流行的开源云端文件系统之一。它是一个基于 FUSE 的文件系统，提供了好几个商业或开源的云存储后端，比如 Amazon S3、Google Cloud Storage、Rackspace CloudFiles，还有 OpenStack。作为一个功能完整的文件系统，S3QL 拥有不少强大的功能：最大 2T 的文件大小、压缩、UNIX 属性、加密、基于写入时复制的快照、不可变树、重复数据删除，以及软、硬链接支持等等。写入 S3QL 文件系统任何数据都将首先被本地压缩、加密，之后才会传输到云后端。当你试图从 S3QL 文件系统中取出内容的时候，如果它们不在本地缓存中，相应的对象会从云端下载回来，然后再即时地解密、解压缩。",-1))]),e[32]||(e[32]=s("p",null,"需要明确的是，S3QL 的确也有它的限制。比如，你不能把同一个 S3FS 文件系统在几个不同的电脑上同时挂载，只能有一台电脑同时访问它。另外，ACL（访问控制列表）也并没有被支持。",-1)),e[33]||(e[33]=s("p",null,"在这篇教程中，我将会描述“如何基于 Amazon S3 用 S3QL 配置一个加密文件系统”。作为一个使用范例，我还会说明如何在挂载的 S3QL 文件系统上运行 rsync 备份工具。",-1)),e[34]||(e[34]=s("h3",{id:"准备工作",tabindex:"-1"},[t("准备工作 "),s("a",{class:"header-anchor",href:"#准备工作","aria-label":"Permalink to “准备工作”"},"​")],-1)),s("p",null,[e[7]||(e[7]=t("本教程首先需要你创建一个 ",-1)),a(l,{href:"http://aws.amazon.com/"},{default:n(()=>[...e[6]||(e[6]=[t("Amazon AWS 帐号",-1)])]),_:1}),e[8]||(e[8]=t("（注册是免费的，但是需要一张有效的信用卡）。",-1))]),s("p",null,[e[10]||(e[10]=t("然后 ",-1)),a(l,{href:"http://aws.amazon.com/"},{default:n(()=>[...e[9]||(e[9]=[t("创建一个 AWS access key",-1)])]),_:1}),e[11]||(e[11]=t("（access key ID 和 secret access key），S3QL 使用这些信息来访问你的 AWS 帐号。",-1))]),e[35]||(e[35]=r(`<p>之后通过 AWS 管理面板访问 AWS S3，并为 S3QL 创建一个新的空 bucket。</p><p><img src="https://farm4.staticflickr.com/3841/15170673701_7d0660e11f_c.jpg" alt=""></p><p>为最佳性能考虑，请选择一个地理上距离你最近的区域。</p><p><img src="https://farm4.staticflickr.com/3902/15150663516_4928d757fc_b.jpg" alt=""></p><h3 id="在-linux-上安装-s3ql" tabindex="-1">在 Linux 上安装 S3QL <a class="header-anchor" href="#在-linux-上安装-s3ql" aria-label="Permalink to “在 Linux 上安装 S3QL”">​</a></h3><p>在大多数 Linux 发行版中都有预先编译好的 S3QL 软件包。</p><h4 id="对于-debian、ubuntu-或-linux-mint" tabindex="-1">对于 Debian、Ubuntu 或 Linux Mint：#### <a class="header-anchor" href="#对于-debian、ubuntu-或-linux-mint" aria-label="Permalink to “对于 Debian、Ubuntu 或 Linux Mint：####”">​</a></h4><pre><code>$ sudo apt-get install s3ql
</code></pre><h4 id="对于-fedora" tabindex="-1">对于 Fedora：#### <a class="header-anchor" href="#对于-fedora" aria-label="Permalink to “对于 Fedora：####”">​</a></h4><pre><code>$ sudo yum install s3ql
</code></pre>`,10)),s("p",null,[e[13]||(e[13]=t("对于 Arch Linux，使用 ",-1)),a(l,{href:"https://aur.archlinux.org/packages/s3ql/"},{default:n(()=>[...e[12]||(e[12]=[t("AUR",-1)])]),_:1}),e[14]||(e[14]=t("。",-1))]),e[36]||(e[36]=r(`<h3 id="首次配置-s3ql" tabindex="-1">首次配置 S3QL <a class="header-anchor" href="#首次配置-s3ql" aria-label="Permalink to “首次配置 S3QL”">​</a></h3><p>在 ~/.s3ql 目录中创建 autoinfo2 文件，它是 S3QL 的一个默认的配置文件。这个文件里的信息包括必须的 AWS access key，S3 bucket 名，以及加密口令。这个加密口令将被用来加密一个随机生成的主密钥，而主密钥将被用来实际地加密 S3QL 文件系统数据。</p><pre><code>$ mkdir ~/.s3ql
$ vi ~/.s3ql/authinfo2
</code></pre><hr><pre><code>[s3]
storage-url: s3://[bucket-name]
backend-login: [your-access-key-id]
backend-password: [your-secret-access-key]
fs-passphrase: [your-encryption-passphrase]
</code></pre><p>指定的 AWS S3 bucket 需要预先通过 AWS 管理面板来创建。</p><p>为了安全起见，让 authinfo2 文件仅对你可访问。</p><pre><code>$ chmod 600 ~/.s3ql/authinfo2
</code></pre><h3 id="创建-s3ql-文件系统" tabindex="-1">创建 S3QL 文件系统 <a class="header-anchor" href="#创建-s3ql-文件系统" aria-label="Permalink to “创建 S3QL 文件系统”">​</a></h3><p>现在你已经准备好可以在 AWS S3 上创建一个 S3QL 文件系统了。</p><p>使用 mkfs.s3ql 工具来创建一个新的 S3QL 文件系统。这个命令中的 bucket 名应该与 authinfo2 文件中所指定的相符。使用“--ssl”参数将强制使用 SSL 连接到后端存储服务器。默认情况下，mkfs.s3ql 命令会在 S3QL 文件系统中启用压缩和加密。</p><pre><code>$ mkfs.s3ql s3://[bucket-name] --ssl
</code></pre><p>你会被要求输入一个加密口令。请输入你在 ~/.s3ql/autoinfo2 中通过“fs-passphrase”指定的那个口令。</p><p>如果一个新文件系统被成功创建，你将会看到这样的输出：</p><p><img src="https://farm6.staticflickr.com/5582/14988587230_e182ca3abd_z.jpg" alt=""></p><h3 id="挂载-s3ql-文件系统" tabindex="-1">挂载 S3QL 文件系统 <a class="header-anchor" href="#挂载-s3ql-文件系统" aria-label="Permalink to “挂载 S3QL 文件系统”">​</a></h3><p>当你创建了一个 S3QL 文件系统之后，下一步便是要挂载它。</p><p>首先创建一个本地的挂载点，然后使用 mount.s3ql 命令来挂载 S3QL 文件系统。</p><pre><code>$ mkdir ~/mnt_s3ql
$ mount.s3ql s3://[bucket-name] ~/mnt_s3ql
</code></pre><p>挂载一个 S3QL 文件系统不需要特权用户，只要确定你对该挂载点有写权限即可。</p><p>视情况，你可以使用“--compress”参数来指定一个压缩算法（如 lzma、bzip2、zlib）。在不指定的情况下，lzma 将被默认使用。注意如果你指定了一个自定义的压缩算法，它将只会应用到新创建的数据对象上，并不会影响已经存在的数据对象。</p><pre><code>$ mount.s3ql --compress bzip2 s3://[bucket-name] ~/mnt_s3ql
</code></pre><p>因为性能原因，S3QL 文件系统维护了一份本地文件缓存，里面包括了最近访问的（部分或全部的）文件。你可以通过“--cachesize”和“--max-cache-entries”选项来自定义文件缓存的大小。</p><p>如果想要除你以外的用户访问一个已挂载的 S3QL 文件系统，请使用“--allow-other”选项。</p><p>如果你想通过 NFS 导出已挂载的 S3QL 文件系统到其他机器，请使用“--nfs”选项。</p><p>运行 mount.s3ql 之后，检查 S3QL 文件系统是否被成功挂载了：</p><pre><code>$ df ~/mnt_s3ql
$ mount | grep s3ql
</code></pre><p><img src="https://farm4.staticflickr.com/3863/15174861482_27a842da3e_z.jpg" alt=""></p><h3 id="卸载-s3ql-文件系统" tabindex="-1">卸载 S3QL 文件系统 <a class="header-anchor" href="#卸载-s3ql-文件系统" aria-label="Permalink to “卸载 S3QL 文件系统”">​</a></h3><p>想要安全地卸载一个（可能含有未提交数据的）S3QL 文件系统，请使用 umount.s3ql 命令。它将会等待所有数据（包括本地文件系统缓存中的部分）成功传输到后端服务器。取决于等待写的数据的多少，这个过程可能需要一些时间。</p><pre><code>$ umount.s3ql ~/mnt_s3ql
</code></pre><h3 id="查看-s3ql-文件系统统计信息及修复-s3ql-文件系统" tabindex="-1">查看 S3QL 文件系统统计信息及修复 S3QL 文件系统 <a class="header-anchor" href="#查看-s3ql-文件系统统计信息及修复-s3ql-文件系统" aria-label="Permalink to “查看 S3QL 文件系统统计信息及修复 S3QL 文件系统”">​</a></h3><p>若要查看 S3QL 文件系统统计信息，你可以使用 s3qlstat 命令，它将会显示诸如总的数据、元数据大小、重复文件删除率和压缩率等信息。</p><pre><code>$ s3qlstat ~/mnt_s3ql
</code></pre><p><img src="https://farm6.staticflickr.com/5559/15184926905_4815e5827a_z.jpg" alt=""></p><p>你可以使用 fsck.s3ql 命令来检查和修复 S3QL 文件系统。与 fsck 命令类似，待检查的文件系统必须首先被卸载。</p><pre><code>$ fsck.s3ql s3://[bucket-name]
</code></pre><h3 id="s3ql-使用案例-rsync-备份" tabindex="-1">S3QL 使用案例：Rsync 备份 <a class="header-anchor" href="#s3ql-使用案例-rsync-备份" aria-label="Permalink to “S3QL 使用案例：Rsync 备份”">​</a></h3><p>让我用一个流行的使用案例来结束这篇教程：本地文件系统备份。为此，我推荐使用 rsync 增量备份工具，特别是因为 S3QL 提供了一个 rsync 的封装脚本（/usr/lib/s3ql/pcp.py）。这个脚本允许你使用多个 rsync 进程递归地复制目录树到 S3QL 目标。</p><pre><code>$ /usr/lib/s3ql/pcp.py -h
</code></pre><p><img src="https://farm4.staticflickr.com/3873/14998096829_d3a64749d0_z.jpg" alt=""></p><p>下面这个命令将会使用 4 个并发的 rsync 连接来备份 ~/Documents 里的所有内容到一个 S3QL 文件系统。</p><pre><code> $ /usr/lib/s3ql/pcp.py -a --quiet --processes=4 ~/Documents ~/mnt_s3ql
</code></pre><p>这些文件将首先被复制到本地文件缓存中，然后在后台再逐步地同步到后端服务器。</p>`,44)),s("p",null,[e[16]||(e[16]=t("若想了解与 S3QL 有关的更多信息，如自动挂载、快照、不可变树，我强烈推荐阅读 ",-1)),a(l,{href:"http://www.rath.org/s3ql-docs/"},{default:n(()=>[...e[15]||(e[15]=[t("官方用户指南",-1)])]),_:1}),e[17]||(e[17]=t("。欢迎告诉我你对 S3QL 怎么看，以及你对任何其他工具的使用经验。",-1))]),e[37]||(e[37]=s("hr",null,null,-1)),s("p",null,[e[19]||(e[19]=t("via: ",-1)),a(l,{href:"http://xmodulo.com/2014/09/create-cloud-based-encrypted-file-system-linux.html"},{default:n(()=>[...e[18]||(e[18]=[t("http://xmodulo.com/2014/09/create-cloud-based-encrypted-file-system-linux.html",-1)])]),_:1})]),s("p",null,[e[23]||(e[23]=t("作者：",-1)),a(l,{href:"http://xmodulo.com/author/nanni"},{default:n(()=>[...e[20]||(e[20]=[t("Dan Nanni",-1)])]),_:1}),e[24]||(e[24]=t(" 译者：",-1)),a(l,{href:"https://github.com/felixonmars"},{default:n(()=>[...e[21]||(e[21]=[t("felixonmars",-1)])]),_:1}),e[25]||(e[25]=t(" 校对：",-1)),a(l,{href:"https://github.com/wxy"},{default:n(()=>[...e[22]||(e[22]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[28]||(e[28]=t("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[26]||(e[26]=[t("LCTT",-1)])]),_:1}),e[29]||(e[29]=t(" 原创翻译，",-1)),a(l,{href:"http://linux.cn/"},{default:n(()=>[...e[27]||(e[27]=[t("Linux中国",-1)])]),_:1}),e[30]||(e[30]=t(" 荣誉推出",-1))])])}const c=o(u,[["render",m]]);export{Q as __pageData,c as default};
